116	/** The run a report came from, when the environment says. All of it is optional. */
117	export interface ReportingRun {
118	  /** The node the reporting run sits on: the issue or pull request number it was working. */
119	  readonly node?: number;
120	  /** The reporting run's own URL. */
121	  readonly runUrl?: string;
122	  /** The agent that filed it. */
123	  readonly agent?: string;
124	}
125	
126	/**
127	 * The "reported from" sentence the started run reads, or `""` when nothing is known.
128	 *
129	 * Prose rather than dispatch inputs, because the started run learns what to do from
130	 * its thread: a run that cannot see where the report came from has no way to go and
131	 * read the pull request or the run that found the defect. "Reported", not "filed": the
132	 * issue may have been filed by an earlier run entirely, and what this line says is
133	 * where the report the agent is about to read came from.
134	 */
135	export function reportedFromLine(report: ReportingRun): string {
136	  const where = report.node === undefined ? "" : `#${report.node}`;
137	  const by = (report.agent ?? "").trim();
138	  const url = (report.runUrl ?? "").trim();
139	  const origin = [where, by === "" ? "" : `by \`${by}\``].filter((part) => part !== "").join(" ");
140	  if (origin === "" && url === "") return "";
141	  const link = url === "" ? "" : ` (${url})`;
142	  return `Reported from ${origin === "" ? "a run" : origin}${link}.`;
143	}
